def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c

    if opp_c == 0:
        return 'D'

    exploit_evidence = False
    for i in range(n - 1):
        if me[i] == 'D' and opp[i + 1] == 'C':
            exploit_evidence = True
            break

    if opp_d == 0:
        if n < 20:
            return 'C'
        if exploit_evidence:
            return 'D'
        if 'D' not in me:
            if n == 20:
                return 'D'
            return 'C'
        if last_me == 'D' and last_opp == 'C':
            return 'C'
        return 'C'

    recent_opp = opp[-10:]
    recent_d = recent_opp.count('D')

    if recent_d >= 7:
        if last_me == 'D' and last_opp == 'D':
            dd = 0
            for i in range(n - 1, -1, -1):
                if me[i] == 'D' and opp[i] == 'D':
                    dd += 1
                else:
                    break
            if dd >= 4 and rng.random() < 0.3:
                return 'C'
        return 'D'

    if last_opp == 'D' and last_me == 'D':
        dd = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'D' and opp[i] == 'D':
                dd += 1
            else:
                break
        if dd >= 3 and rng.random() < 0.5:
            return 'C'
        if n >= 4 and opp[-4:].count('D') >= 3:
            return 'D'
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if recent_d >= 3:
            return 'D'
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    if last_opp == 'C':
        if last_me == 'D':
            if exploit_evidence:
                return 'D'
            return 'C'
        run_c = 0
        for a in reversed(opp):
            if a == 'C':
                run_c += 1
            else:
                break
        if run_c >= 5 and n >= 20:
            if rng.random() < 0.15:
                return 'D'
        return 'C'

    return 'C'
